# Claude Cowork (Amazon Bedrock) - machine-wide uninstaller for Windows.
#
# GENERATED by scripts/install/build-windows-cowork.sh for release 2026-11-18-154836. Do not edit by hand.
# Deploy as an Intune platform script with the same settings as install-cowork.ps1
# (SYSTEM, 64-bit PowerShell host).
#
# Removes only what install-cowork.ps1 recorded in HKLM\SOFTWARE\ccwb: the policy values it wrote
# under HKLM\SOFTWARE\Policies\Claude (restoring any value it had overwritten; the key itself is
# removed only if it is then empty), the organization plugin folder(s) it recorded under
# C:\Program Files\Claude\org-plugins (nothing else in that directory), the marker, and
# C:\ProgramData\ccwb (the live folder, entries of the older layout, and the container once empty). Without the marker it changes nothing. Per-user credential caches in user profiles are left alone.
#
# Test override (never set in production): CCWB_INSTALL_ROOT, CCWB_ORG_PLUGINS_ROOT, CCWB_POLICY_KEY, CCWB_MARKER_KEY, CCWB_LOG.
#Requires -Version 5.1
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-Setting([string]$Name, [string]$Default) {
    $v = [Environment]::GetEnvironmentVariable($Name)
    if ([string]::IsNullOrEmpty($v)) { return $Default }
    return $v
}
$ImeLogs = 'C:\ProgramData\Microsoft\IntuneManagementExtension\Logs'
if (Test-Path -LiteralPath $ImeLogs -PathType Container) { $DefaultLog = "$ImeLogs\ccwb-cowork.log" }
else { $DefaultLog = "$env:windir\Logs\ccwb-cowork.log" }
# Container (administrator-only, never renamed) and the live install inside it; see install-cowork.ps1.
$InstallBase = Get-Setting 'CCWB_INSTALL_ROOT' 'C:\ProgramData\ccwb'
$InstallRoot = Join-Path $InstallBase 'live'
$PolicyKey   = Get-Setting 'CCWB_POLICY_KEY'   'HKLM:\SOFTWARE\Policies\Claude'
$MarkerKey   = Get-Setting 'CCWB_MARKER_KEY'   'HKLM:\SOFTWARE\ccwb'
$OrgPluginsRoot = Get-Setting 'CCWB_ORG_PLUGINS_ROOT' 'C:\Program Files\Claude\org-plugins'
$LogFile     = Get-Setting 'CCWB_LOG'          $DefaultLog

function Write-Log([string]$Message) {
    $line = '{0} ccwb-cowork-uninstall: {1}' -f (Get-Date -Format 's'), $Message
    Write-Output $line
    try { Add-Content -LiteralPath $LogFile -Value $line } catch { }
}
# A plugin name read back from the registry is never trusted as a path: plain lower-case folder names only, and
# nothing Windows treats specially (trailing dot is stripped; CON/NUL/COM1... are devices).
function Test-PluginName([string]$Name) {
    return ($Name -cmatch '\A[a-z0-9][a-z0-9._-]*\z') -and (-not $Name.EndsWith('.')) -and
           (-not ($Name -cmatch '\A(con|prn|aux|nul|com[0-9]|lpt[0-9])(\.|\z)'))
}
function Stop-Uninstall([string]$Message) { Write-Log "ERROR: $Message"; exit 1 }
function Get-RegValue([string]$Key, [string]$Name) {
    if (-not (Test-Path -LiteralPath $Key)) { return $null }
    return (Get-Item -LiteralPath $Key).GetValue($Name, $null, 'DoNotExpandEnvironmentNames')
}

if (-not [Environment]::Is64BitProcess) {
    Stop-Uninstall 'running in 32-bit PowerShell: enable "Run script in 64 bit PowerShell Host" in Intune'
}
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Stop-Uninstall 'must run as SYSTEM or an administrator'
}
if (-not (Test-Path -LiteralPath $MarkerKey)) {
    Write-Log "no install record at $MarkerKey; nothing to remove"
    exit 0
}

# --- Mark the install INCOMPLETE before changing anything ------------------------------------
# Release/hash/digest are what install-cowork.ps1 treats as "already installed". Clear them first, keeping the
# ownership and backup records (PolicyNames, PriorValues, OrgPlugins) a retry needs. Otherwise a later failure
# (a locked plugin or helper file) would leave policy removed but the marker saying "complete", and re-running the
# installer would report "already installed" without restoring anything.
foreach ($field in @('Release', 'PackageSha256', 'PolicyDigest')) {
    Remove-ItemProperty -LiteralPath $MarkerKey -Name $field -ErrorAction SilentlyContinue
}

# --- Policy: remove our values, restore what we overwrote -----------------------------------
# PS 5.1 ConvertFrom-Json emits an array as ONE object: enumerate it, never wrap it in @(...).
$names = New-Object System.Collections.Generic.List[string]
$recordedNames = Get-RegValue $MarkerKey 'PolicyNames'
if ($recordedNames) { foreach ($x in ($recordedNames | ConvertFrom-Json)) { $names.Add([string]$x) } }
$prior = @{}
$recordedPrior = Get-RegValue $MarkerKey 'PriorValues'
if ($recordedPrior) { foreach ($p in ($recordedPrior | ConvertFrom-Json).PSObject.Properties) { $prior[$p.Name] = [string]$p.Value } }

if (Test-Path -LiteralPath $PolicyKey) {
    foreach ($n in $names) {
        if ($prior.ContainsKey($n)) {
            New-ItemProperty -LiteralPath $PolicyKey -Name $n -Value ([string]$prior[$n]) -PropertyType String -Force | Out-Null
        } else {
            Remove-ItemProperty -LiteralPath $PolicyKey -Name $n -ErrorAction SilentlyContinue
        }
    }
    $key = Get-Item -LiteralPath $PolicyKey
    if ($key.ValueCount -eq 0 -and $key.SubKeyCount -eq 0) { Remove-Item -LiteralPath $PolicyKey -Force }
}

# --- Organization plugins: only the folders the installer recorded --------------------------
# PS 5.1 ConvertFrom-Json emits an array as ONE object: enumerate it, never wrap it in @(...).
$pluginNames = New-Object System.Collections.Generic.List[string]
$recordedPlugins = Get-RegValue $MarkerKey 'OrgPlugins'
if ($recordedPlugins) { foreach ($x in ($recordedPlugins | ConvertFrom-Json)) { $pluginNames.Add([string]$x) } }
foreach ($plugin in $pluginNames) {
    # The name comes from the registry: accept a plain folder name only, never a path.
    if (-not (Test-PluginName $plugin)) { Write-Log "skipping unsafe recorded plugin name"; continue }
    $pluginDir = Join-Path $OrgPluginsRoot $plugin
    if (-not (Test-Path -LiteralPath $pluginDir)) { continue }
    $pluginAside = Join-Path (Split-Path -Parent $OrgPluginsRoot) ('.ccwb-old-' + [IO.Path]::GetRandomFileName())
    try { [IO.Directory]::Move($pluginDir, $pluginAside) }
    catch { Stop-Uninstall "plugin $plugin is in use (Claude Desktop running?); quit Claude and retry: $($_.Exception.Message)" }
    $eap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { & cmd.exe /d /c rd /s /q "`"$pluginAside`"" 2>&1 | Out-Null } finally { $ErrorActionPreference = $eap }
    if (Test-Path -LiteralPath $pluginAside) { Write-Log "plugin files left at $pluginAside (in use); delete after reboot" }
    else { Write-Log "removed organization plugin $plugin" }
}

# --- Files: rename aside (fails cleanly while in use), then delete --------------------------
if (Test-Path -LiteralPath $InstallRoot) {
    $aside = Join-Path $InstallBase ('.old-' + [IO.Path]::GetRandomFileName())
    try { [IO.Directory]::Move($InstallRoot, $aside) }
    catch { Stop-Uninstall "install is in use (Claude Desktop running?); quit Claude and retry: $($_.Exception.Message)" }
    $eap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    # rd /s removes junctions/symlinks themselves and never follows them.
    try { & cmd.exe /d /c rd /s /q "`"$aside`"" 2>&1 | Out-Null } finally { $ErrorActionPreference = $eap }
    if (Test-Path -LiteralPath $aside) { Write-Log "files left at $aside (in use); delete after reboot" }
}

# Entries earlier releases left directly in the container, then the container itself ONLY if it is now empty.
$eap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
foreach ($legacy in @('credential-process-windows.exe', 'config.json', 'version.json', 'aws')) {
    $legacyPath = Join-Path $InstallBase $legacy
    if (-not (Test-Path -LiteralPath $legacyPath)) { continue }
    try { & cmd.exe /d /c rd /s /q "`"$legacyPath`"" 2>&1 | Out-Null } catch { }
    if (Test-Path -LiteralPath $legacyPath -PathType Leaf) { Remove-Item -LiteralPath $legacyPath -Force -ErrorAction SilentlyContinue }
}
# Leftovers of interrupted installs, inside the container and the old sibling names beside it.
foreach ($pat in @(@($InstallBase, '.staging-*'), @($InstallBase, '.old-*'),
                   @((Split-Path -Parent $InstallBase), ((Split-Path -Leaf $InstallBase) + '.staging-*')),
                   @((Split-Path -Parent $InstallBase), ((Split-Path -Leaf $InstallBase) + '.old-*')))) {
    if (-not (Test-Path -LiteralPath $pat[0])) { continue }
    foreach ($left in @(Get-ChildItem -LiteralPath $pat[0] -Directory -Force -Filter $pat[1])) {
        if ($left.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
        try { & cmd.exe /d /c rd /s /q "`"$($left.FullName)`"" 2>&1 | Out-Null } catch { }
    }
}
$ErrorActionPreference = $eap
try { [IO.Directory]::Delete($InstallBase, $false) } catch { Write-Log "left $InstallBase (not empty)" }

Remove-Item -LiteralPath $MarkerKey -Recurse -Force
Write-Log "removed $($names.Count) policy values ($($prior.Count) restored), $($pluginNames.Count) recorded organization plugin(s), marker and $InstallRoot"
exit 0
